package nl.smartstreamlabs.sbwdroneconfig;
import com.google.gson.*;import java.util.*;import java.io.*;import net.minecraft.core.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;import org.joml.Matrix4d;import org.joml.Vector3d;
/** Shared native model transforms and cached collision, all distances in blocks. */
public final class DefenseGeometry{
 public static final DefenseGeometry[]MODELS={new DefenseGeometry("pl01"),new DefenseGeometry("dr01")};
 public record Bone(String name,int parent,Vector3d pivot){}public record Mount(int bone,Vector3d exit,Vector3d direction){}
 public final String key;public final List<Bone>bones=new ArrayList<>();public final List<Mount>mounts=new ArrayList<>();public final int[][]cells,support;public final AABB bounds,panel;private final JsonObject animations;private final List<AABB>[]poses;private final Map<Integer,VoxelShape[]>shapes=new HashMap<>();
 private DefenseGeometry(String key){this.key=key;try(var r=new InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/assets/sbwdroneconfig/defense/"+key+".json")),java.nio.charset.StandardCharsets.UTF_8)){var j=JsonParser.parseReader(r).getAsJsonObject();for(var v:j.getAsJsonArray("bones")){var n=v.getAsJsonObject();bones.add(new Bone(n.get("name").getAsString(),n.get("parent").getAsInt(),vec(n.getAsJsonArray("pivot"))));}for(var v:j.getAsJsonArray("mounts")){var n=v.getAsJsonObject();mounts.add(new Mount(n.get("bone").getAsInt(),vec(n.getAsJsonArray("exit")),vec(n.getAsJsonArray("direction"))));}cells=ints(j.getAsJsonArray("cells"));support=ints(j.getAsJsonArray("support"));bounds=box(j.getAsJsonArray("bounds"));panel=box(j.getAsJsonArray("panel"));animations=j.getAsJsonObject("animations");poses=new List[13];for(int i=0;i<13;i++){poses[i]=new ArrayList<>();for(var v:j.getAsJsonArray("poses").get(i).getAsJsonArray())poses[i].add(box(v.getAsJsonArray()));}}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 private static Vector3d vec(JsonArray a){return new Vector3d(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}private static AABB box(JsonArray a){return new AABB(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble(),a.get(3).getAsDouble(),a.get(4).getAsDouble(),a.get(5).getAsDouble());}private static int[][]ints(JsonArray a){int[][]v=new int[a.size()][3];for(int i=0;i<v.length;i++)for(int k=0;k<3;k++)v[i][k]=a.get(i).getAsJsonArray().get(k).getAsInt();return v;}
 public static Matrix4d world(BlockPos root,Direction facing){return new Matrix4d().translation(root.getX()+.5,root.getY(),root.getZ()+.5).rotateY(Math.toRadians(-facing.toYRot()));}
 public static Vec3 point(Matrix4d m,Vector3d v){var a=m.transformPosition(new Vector3d(v));return new Vec3(a.x,a.y,a.z);}public static Vec3 direction(Matrix4d m,Vector3d v){var a=m.transformDirection(new Vector3d(v)).normalize();return new Vec3(a.x,a.y,a.z);}
 public Vector3d sample(String clip,String bone,String channel,double time){var anim=animations.getAsJsonObject(clip);if(anim==null)return new Vector3d();var tracks=anim.getAsJsonObject("tracks");if(!tracks.has(bone))return new Vector3d();JsonObject last=null;for(var value:tracks.getAsJsonArray(bone)){var k=value.getAsJsonObject();if(!k.get("channel").getAsString().equals(channel))continue;double t=k.get("time").getAsDouble();if(time<=t){if(last==null)return vec(k.getAsJsonArray("value"));double previous=last.get("time").getAsDouble();return vec(last.getAsJsonArray("value")).lerp(vec(k.getAsJsonArray("value")),Math.max(0,Math.min(1,(time-previous)/Math.max(.00001,t-previous))));}last=k;}return last==null?new Vector3d():vec(last.getAsJsonArray("value"));}
 public Matrix4d[]transforms(double service,double scanTime,float[]covers){var result=new Matrix4d[bones.size()];for(int i=0;i<result.length;i++){var b=bones.get(i);String clip=key+".lower_to_service";double length=key.equals("pl01")?4:3;var rotation=sample(clip,b.name,"rotation",service*length);var position=sample(clip,b.name,"position",service*length).add(sample(key+".jacks_retract",b.name,"position",service*1.5)).div(16);if(b.name.equals("Radar_Azimuth")&&scanTime>=0)rotation.add(sample("dr01.scan_sweep",b.name,"rotation",scanTime%10));if(b.name.startsWith("Muzzle_Cover_")){int slot=Integer.parseInt(b.name.substring(b.name.length()-2))-1;rotation.add(sample(String.format(java.util.Locale.ROOT,"pl01.open_cover_%02d",slot+1),b.name,"rotation",covers[slot]*.8));}result[i]=new Matrix4d(b.parent<0?new Matrix4d():result[b.parent]).translate(b.pivot).translate(position).rotateZYX(Math.toRadians(rotation.z),Math.toRadians(rotation.y),Math.toRadians(rotation.x)).translate(-b.pivot.x,-b.pivot.y,-b.pivot.z);}return result;}
 public Vec3 exit(BlockPos root,Direction face,int slot,double service){var m=mounts.get(slot);return point(world(root,face).mul(transforms(service,-1,new float[4])[m.bone]),m.exit);}public Vec3 launchDirection(BlockPos root,Direction face,int slot,double service){var m=mounts.get(slot);return direction(world(root,face).mul(transforms(service,-1,new float[4])[m.bone]),m.direction);}
 public BlockPos cell(BlockPos root,Direction face,int[]c){var p=point(world(BlockPos.ZERO,face),new Vector3d(c[0],c[1],c[2]));return root.offset((int)Math.round(p.x-.5),c[1],(int)Math.round(p.z-.5));}public BlockPos root(BlockPos p,Direction f,int part){return p.subtract(cell(BlockPos.ZERO,f,cells[part]));}
 public AABB worldBox(BlockPos root,Direction f,AABB b){var m=world(root,f);double x0=1e10,y0=1e10,z0=1e10,x1=-1e10,y1=-1e10,z1=-1e10;for(double x:new double[]{b.minX,b.maxX})for(double y:new double[]{b.minY,b.maxY})for(double z:new double[]{b.minZ,b.maxZ}){var p=point(m,new Vector3d(x,y,z));x0=Math.min(x0,p.x);y0=Math.min(y0,p.y);z0=Math.min(z0,p.z);x1=Math.max(x1,p.x);y1=Math.max(y1,p.y);z1=Math.max(z1,p.z);}return new AABB(x0,y0,z0,x1,y1,z1);}
 public VoxelShape collision(Direction facing,int part,int pose){int code=Math.max(0,Math.min(12,pose))*4+facing.get2DDataValue();var cached=shapes.get(code);if(cached==null){cached=new VoxelShape[cells.length];var worldBoxes=poses[Math.max(0,Math.min(12,pose))].stream().map(b->worldBox(BlockPos.ZERO,facing,b)).toList();for(int i=0;i<cells.length;i++){var p=cell(BlockPos.ZERO,facing,cells[i]);var shape=Shapes.empty();for(var b:worldBoxes){double x0=Math.max(0,b.minX-p.getX()),y0=Math.max(0,b.minY-p.getY()),z0=Math.max(0,b.minZ-p.getZ()),x1=Math.min(1,b.maxX-p.getX()),y1=Math.min(1,b.maxY-p.getY()),z1=Math.min(1,b.maxZ-p.getZ());if(x1>x0&&y1>y0&&z1>z0)shape=Shapes.or(shape,Shapes.box(x0,y0,z0,x1,y1,z1));}cached[i]=shape.optimize();}shapes.put(code,cached);}return cached[part];}
}
